std::mt19937 gen(rd());
std::normal_distribution<double> dist(0.0, 1.0);

double total_mass = 0.0;
vec3 com_velocity(0.0, 0.0, 0.0);

for (size_t i = 0; i < masses.size(); ++i) {
    total_mass += masses[i];
    velocities[i] = vec3(dist(gen), dist(gen), dist(gen));
    velocities[i] = velocities[i] * std::sqrt(temperature / masses[i]);
}

for (size_t i = 0; i < masses.size(); ++i) {
    com_velocity = com_velocity + velocities[i] * masses[i];
}

com_velocity = com_velocity / total_mass;

for (size_t i = 0; i < velocities.size(); ++i) {
    velocities[i] = velocities[i] - com_velocity;
}

